fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    // Enumerate all pairs (p, q) with 0 <= p < q < n in lexicographic order.
    for p in 0..n - 1 {
        for q in p + 1..n {
            if nums[p] + nums[q] == target {
                return (p, q);
            }
        }
    }
    // By problem assumption, we must have found a valid pair.
    unreachable!("No two-sum solution exists");
}

